    if ' ':  union(base+0,base+1), union(base+1,base+2), union(base+2,base+3)
    if '/':  union(base+0,base+3), union(base+1,base+2)
    if '\':  union(base+0,base+1), union(base+2,base+3)
    if c+1 < n:  union(base+1, 4*(r*n+c+1)+3)
    if r+1 < n:  union(base+2, 4*((r+1)*n+c)+0)
count distinct roots among all 4*n*n vertices
