code.cpp:
class Solution {
public:
    int regionsBySlashes(vector<string>& grid) {
        int n = grid.size();
        int N = 4 * n * n;
        vector<int> parent(N);
        for (int i = 0; i < N; i++) parent[i] = i;

        auto find = [&](int x) -> int {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        };

        auto unite = [&](int a, int b) {
            int ra = find(a), rb = find(b);
            if (ra != rb) parent[ra] = rb;
        };

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                int base = 4 * (r * n + c);
                char ch = grid[r][c];
                if (ch == ' ') {
                    unite(base + 0, base + 1);
                    unite(base + 1, base + 2);
                    unite(base + 2, base + 3);
                } else if (ch == '/') {
                    unite(base + 0, base + 3);
                    unite(base + 1, base + 2);
                } else {
                    unite(base + 0, base + 1);
                    unite(base + 2, base + 3);
                }
                if (c + 1 < n) {
                    int rbase = 4 * (r * n + c + 1);
                    unite(base + 1, rbase + 3);
                }
                if (r + 1 < n) {
                    int bbase = 4 * ((r + 1) * n + c);
                    unite(base + 2, bbase + 0);
                }
            }
        }

        int count = 0;
        for (int i = 0; i < N; i++) {
            if (find(i) == i) count++;
        }
        return count;
    }
};
